import { describe, test, expect } from "vitest";
import { produce, enableArrayMethods } from "../src/immer";

enableArrayMethods();

describe("immer regression", () => {
  test("basic produce", () => {
    const base = { a: 1, b: { c: 2 } };
    const next = produce(base, (d) => { d.a = 2; d.b.c = 3; });
    expect(next.a).toBe(2);
    expect(next.b.c).toBe(3);
    expect(base.a).toBe(1);
  });
  test("array push", () => {
    const base = [1,2,3] as number[];
    const next = produce(base, d => { d.push(4); });
    expect(next).toEqual([1,2,3,4]);
    expect(base).toEqual([1,2,3]);
  });

  test("reverse then mutate should not mutate base", () => {
    const base = [{a: 1}, {a: 2}];
    const next = produce(base, draft => {
      draft.reverse();
      draft[0].a = 3;
    });
    expect(next).toEqual([{a: 3}, {a: 1}]);
    expect(base).toEqual([{a: 1}, {a: 2}]);
  });

  test("sort then mutate should not mutate base", () => {
    const base = [{a: 3}, {a: 1}, {a: 2}];
    const next = produce(base, draft => {
      draft.sort((a, b) => a.a - b.a);
      draft[0].a = 10;
    });
    expect(next).toEqual([{a: 10}, {a: 2}, {a: 3}]);
    expect(base).toEqual([{a: 3}, {a: 1}, {a: 2}]);
  });

  test("reverse twice then mutate should not mutate base", () => {
    const base = [{a: 1}, {a: 2}];
    const next = produce(base, draft => {
      draft.reverse();
      draft.reverse();
      draft[0].a = 99;
    });
    expect(next).toEqual([{a: 99}, {a: 2}]);
    expect(base).toEqual([{a: 1}, {a: 2}]);
  });
});

